def get_total_number_of_sequences(m, n):
    # Helper function to check if a sequence is valid
    def is_valid_sequence(seq):
        for i in range(1, len(seq)):
            if seq[i] < 2 * seq[i - 1]:
                return False
        return True

    # Dynamic programming table initialization
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: there's one way to form a sequence of length 1 with any number from 2 to m
    for j in range(2, m + 1):
        dp[1][j] = 1

    # Fill the DP table
    for i in range(2, n + 1):
        for j in range(2, m + 1):
            dp[i][j] = sum(dp[i-1][k] for k in range(2, j + 1))

    # Sum up all valid sequences of length n
    total_sequences = sum(dp[n][j] for j in range(2, m + 1))
    return total_sequences

