def maxAverageOfPath(matrix):
    n = len(matrix)
    dp = [[-1] * n for _ in range(n)]

    def dfs(x, y):
        if x == n - 1 and y == n - 1:
            return matrix[x][y]

        if dp[x][y] != -1:
            return dp[x][y]

        right_cost = dfs(x + 1, y) if x < n - 1 else float('-inf')
        down_cost = dfs(x, y + 1) if y < n - 1 else float('-inf')

        dp[x][y] = matrix[x][y] + max(right_cost, down_cost)
        return dp[x][y]

    return dfs(0, 0) / (n * n)

