def bell_number(n):
    # Initialize a list to store Bell numbers up to n
    bell = [0] * (n + 1)
    bell[0] = 1  # Base case: B0 = 1

    # Function to compute the next Bell number using the previous ones
    def compute_bell(i):
        if i == 0:
            return 1
        result = 0
        for j in range(i):
            result += bell[j] * binomial_coefficient(i - 1, j)
        return result

    # Function to compute binomial coefficient C(n, k)
    def binomial_coefficient(n, k):
        if k > n:
            return 0
        if k == 0 or k == n:
            return 1
        return binomial_coefficient(n - 1, k - 1) + binomial_coefficient(n - 1, k)

    # Compute Bell numbers from 1 to n
    for i in range(1, n + 1):
        bell[i] = compute_bell(i)

    return bell[n]

