def bell_number(n):
    # Initialize a list to store Bell numbers up to n
    bell = [0] * (n + 1)
    bell[0] = 1  # Base case: B(0) = 1

    # Function to calculate binomial coefficients
    def binomial_coefficient(n, k):
        if k > n:
            return 0
        if k == 0 or k == n:
            return 1
        return binomial_coefficient(n - 1, k - 1) + binomial_coefficient(n - 1, k)

    # Calculate Bell numbers using the recursive formula
    for i in range(1, n + 1):
        bell[i] = sum(bell[j] * binomial_coefficient(i - 1, j) for j in range(i))

    return bell[n]

