def maxAverageOfPath(matrix):
    N = len(matrix)

    @lru_cache(None)
    def dfs(x, y, total_cost, count):
        if x == N - 1 and y == N - 1:
            return (total_cost + matrix[x][y], count + 1)

        right = float('-inf'), 0
        if y < N - 1:
            right = dfs(x, y + 1, total_cost + matrix[x][y], count + 1)

        down = float('-inf'), 0
        if x < N - 1:
            down = dfs(x + 1, y, total_cost + matrix[x][y], count + 1)

        return max(right, down)

    max_avg, _ = dfs(0, 0, 0, 0)
    return max_avg / (N * N)

