    count = 0
    num = 2
    while True:
        if (is_prime(num - 1) and is_prime((num * num - 1) // 2)) or \
           (is_prime(num + 1) and is_prime((num * num + 1) // 2)):
            count += 1
            if count == n:
                return num
        num += 1

